$n=0;function ok(bool $v,string $m):void{global $n;if(!$v)throw new RuntimeException($m);echo "PASS $m\n";++$n;}function denied(callable $f,string $m):void{try{$f();}catch(DomainException){ok(true,$m);return;}throw new RuntimeException($m);}
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','A');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','members',1),('member','a','member',0)");$f=new Finance($db,'admin');$x=new DatevExport($db,'admin');$key=fn()=>bin2hex(random_bytes(16));$bank=$f->createAccount('Bank','offline','0','2026-01-01');
