$f->reverse($entry,2,'2026-02-03','Test correction');$feb=array_replace($o,['from'=>'2026-02-01','to'=>'2026-02-28']);$p2=$x->preview($feb);$rows=explode("\r\n",substr($x->download($feb,$p2['hash']),3));$r=str_getcsv($rows[2],';','"','');ok($r[1]==='S'&&$r[117]==='1'&&$p2['signed_total_cents']===-1001,'reversal has original direction plus Generalumkehr');
$bad=$x->preview(array_replace($o,['bank_codes'=>[]]));ok((bool)$bad['errors'],'missing money account reported');denied(fn()=>$x->download($bad['options'],$bad['hash']),'invalid rows block whole export');denied(fn()=>$x->download($o,str_repeat('0',64)),'stale preview blocked');denied(fn()=>(new DatevExport($db,'member'))->preview($o),'member export denied');denied(fn()=>$x->preview(array_replace($o,['advisor'=>'1'])),'invalid DATEV metadata blocked');
$f->createTransaction(['account'=>$bank,'booked_on'=>'2026-01-03','direction'=>'income','amount'=>'1','description'=>'Unassigned'],$key());denied(fn()=>$x->download($o,$p['hash']),'new transaction invalidates reviewed snapshot');$new=$x->preview($o);ok((bool)array_filter($new['errors'],fn($e)=>str_contains($e['message'],'keinem Beleg')),'unassigned payment visible');
